contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint256 reqID) public {
        // The test contract is not the owner recorded in the clone's immutable args,
        // so any rescind attempt from here must be rejected.
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;
        require(ownerBefore != address(this));
        bool reverted;
        c.rescindRequest(reqID); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        assert(reverted);
    }
    receive() external payable {}
}

