pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Cooler} from "../src/Cooler.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Cooler c;

    function setUp() public {
        c = new Cooler();
    }

    function _run(uint256 reqID) internal {
        address ownerBefore;
        try c.owner() returns (address __r) { ownerBefore = __r; } catch { return; }
        vm.assume(ownerBefore != address(this));
        bool reverted;
        try c.rescindRequest(reqID) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted);
    }

    function testFuzz_run(uint256 reqID) public {
        _run(reqID);
    }

    receive() external payable {}
}
